static inline int max(int a, int b)
{
  return a > b ? a : b;
}

/* Complete elliptic integrals K(k), E(k) for the kernel modulus
   k = sqrt(1/(1+C1)), computed from the complementary parameter
   mp = 1 - k^2 = C1/(1+C1) by the arithmetic-geometric mean.
   Near the particle C1 -> 0 and k -> 1: forming k first rounds away the
   complement (1 - k^2 is then only known to ~eps/C1 relative error), which
   contaminates K and E and, through them, the m-mode fields. Feeding the
   complement keeps both accurate for arbitrarily small C1. */
static void effsource_ellKE_from_C1(double C1, double *ellK, double *ellE)
{
  const double mp = C1 / (1.0 + C1);
  double a = 1.0, b = sqrt(mp);
  double S = 0.5 * (1.0 - mp);   /* c_0^2/2 without ever forming k */
  double w = 1.0;                /* 2^{n-1} for the E-series */
  for (int n = 0; n < 100; n++) {
    const double cn = 0.5 * (a - b);
    const double an = 0.5 * (a + b);
    b = sqrt(a * b);
    a = an;
    S += w * cn * cn;
    w *= 2.0;
    if (fabs(cn) <= DBL_EPSILON * fabs(a)) break;
  }
  *ellK = M_PI / (2.0 * a);
  *ellE = *ellK * (1.0 - S);
}

/* Log-split of the complete elliptic integrals about the particle:
     K = PK + QK*ln(1/m1),  E = PE + QE*ln(1/m1),  m1 = C1/(1+C1),
   with PK, QK, PE, QE analytic in m1 (A&S 17.3.35-36).  The log
   coefficients are exactly QK = K(m1)/pi and QE = (K(m1)-E(m1))/pi, where
   K(m1), E(m1) are the integrals evaluated AT PARAMETER m1 (the "primed"
   side, small argument near the particle).  Since ln(1/m1) carries the
   whole ln(alpha) content of the kernel (C1 = alpha/beta), this split is
   what isolates the analytic and ln(alpha) parts of the m-mode fields. */
static void effsource_ellKE_PQ_from_C1(double C1, double *PK, double *QK,
                                       double *PE, double *QE)
{
  if (C1 <= 0.0)
  {
    /* exact m1 -> 0 limits of the analytic parts */
    *PK = 2.0 * M_LN2;
    *QK = 0.5;
    *PE = 1.0;
    *QE = 0.0;
    return;
  }

  double ellK, ellE, Kp, Ep;
  effsource_ellKE_from_C1(C1, &ellK, &ellE);

  const double m1 = C1 / (1.0 + C1);
  if (m1 < 1e-6)
  {
    /* small-parameter series for the primed integrals; next term O(m1^3) */
    Kp = 0.5 * M_PI * (1.0 + m1 * (0.25 + m1 * (9.0 / 64.0)));
    Ep = 0.5 * M_PI * (1.0 - m1 * (0.25 + m1 * (3.0 / 64.0)));
  }
  else
  {
    /* K(m1), E(m1): complement of m1 is 1/(1+C1), i.e. the C1 -> 1/C1 dual */
    effsource_ellKE_from_C1(1.0 / C1, &Kp, &Ep);
  }

  const double lninv = -log(m1);
  *QK = Kp / M_PI;
  *QE = (Kp - Ep) / M_PI;
  *PK = ellK - *QK * lninv;
  *PE = ellE - *QE * lninv;
}

/* Taylor coefficients in m1 = C1/(1+C1) for the log-split pieces
   K(1-m1) = PK + QK*ln(1/m1), E(1-m1) = PE + QE*ln(1/m1), used for
   the |m1| < 0.1 branch of the PQ primitive where the closed-form
   Legendre-derivative expressions suffer 1/m1, 1/m1^2 cancellation.
   Long double: the split assembly cancels ~C1^3 near the particle,
   so every input factor needs better-than-double relative accuracy. */
